export function validateConfig(config, sourcePath) {
  const errors = [];
  if (!config.entry) errors.push({ code: 'ENTRY_REQUIRED', sourcePath, line: 3, message: 'entry is required' });
  return errors;
}
export function renderFailure(errors) {
  return `Validation failed (${errors.length})`;
}
export const advice = { ENTRY_REQUIRED: 'Set entry to the local source file path.' };

arguments.command:
node --input-type=module <<'NODE'
import { validateConfig, renderFailure, advice } from './src/diagnostics.mjs';
for (const [label, config] of [['missing entry', {}], ['empty entry', { entry: '' }], ['present entry', { entry: './src/main.mjs' }]]) {
  const errors = validateConfig(config, 'config.json');
  console.log(JSON.stringify({ label, errors, rendered: renderFailure(errors), availableAdvice: errors.map(error => advice[error.code]) }));
}
NODE
nl -ba src/diagnostics.mjs

